struct Fixture {
 std::shared_ptr<CommonCatalog> catalog=std::make_shared<CommonCatalog>();CommonStore c{CommonState{},catalog};PrivateShopState shops;PrivateShopCommandResultsState results;
 Fixture(){c.state().identity.world_id[0]=1;c.state().metadata.player_actor_id="owner";for(const StableId id:{"owner","worker"}){ActorRecord a;a.id=id;c.state().actors.insert(id,a);c.state().request_sequences.insert(id,0);}}
 StableId opening(){auto id=c.next_id("private_shop").value;PrivateShopRecord shop;shop.id=id;shop.opened_tick=c.tick();shop.terms.proprietor_actor_id="owner";shops.shops.insert(id,shop);check(c.append_fact({id,"private_shop_opened","private_shops"}).ok,"source header");return id;}
 std::shared_ptr<CommitResult> commit(const StableId& kind,const StableId& source,Integer request,const StableId& actor="owner"){auto r=std::make_shared<CommitResult>();r->kind=kind;r->result_id=c.next_id("result").value;r->tick=c.tick();r->revision=++c.state().identity.revision;InteractionEffect e;e.settlement_result=source;auto details=std::make_shared<ReceiptDetails>();details->data=e;if(kind=="family_retire"||kind=="family_continue_as"||kind=="family_legacy_activate"){FamilyEffect f;f.fact_id=source;f.heir_actor_id="worker";f.player_actor_id="worker";details->data=f;}r->details=details;c.state().request_sequences.set(actor,request);c.state().results.set(actor+":"+std::to_string(request),r);c.state().history.push_back({r->tick,kind,actor,r->result_id,{}});return r;}
};
// 十三种原表都走同一个严格头覆盖口；这里仅验证载荷投影，不冒经营全史夹具。
template<class T>StableId source(Fixture& f,OrderedTable<T>& table,const StableId& prefix,const StableId& kind){auto id=f.c.next_id(prefix).value;T value;value.id=id;check(table.insert(id,std::move(value)),"source table insertion");check(f.c.append_fact({id,kind,"private_shops"}).ok,"source Common header");return id;}
