 const auto capital=source(f,f.shops.capital,"private_shop_capital","private_shop_capital_added");source(f,f.shops.markups,"private_shop_markup","private_shop_markup_changed");source(f,f.shops.purchases,"private_shop_stock","private_shop_stock_received");const auto operation=source(f,f.shops.operations,"action","private_shop_operating_started");source(f,f.shops.operating_results,"private_shop_day","private_shop_operating_interrupted");const auto staff=source(f,f.shops.staff.contracts,"private_shop_staff","private_shop_staff_accepted");source(f,f.shops.staff.decisions,"private_shop_staff_decision","private_shop_staff_ended");source(f,f.shops.staff.services,"private_shop_staff_service","private_shop_staff_served");const auto order=source(f,f.shops.orders.orders,"private_shop_order","private_shop_order_issued");source(f,f.shops.orders.bindings,"private_shop_order_bound","private_shop_order_bound");source(f,f.shops.order_settlements,"private_shop_order_settlement","private_shop_order_settled");source(f,f.shops.closings,"private_shop_closed","private_shop_closed");
